SELECT * FROM MBR_TNOCS_STATS WHERE 1=1
AND CRTR_YR = (SELECT MAX(CRTR_YR) FROM MBR_TNOCS_STATS)
AND CRTR_YR = #{shYear}

SELECT *
FROM LCLGV_AOD_STATS
WHERE 1=1

	AND CRTR_YR = (SELECT MAX(CRTR_YR) FROM LCLGV_AOD_STATS)


	AND CRTR_YR = #{shYear}


	AND MCTPV_CD = #{shMctpv}

		AND LCLGV_CD = #{shLclgv}

	ORDER BY MCTPV_CD, LCLGV_CD


	ORDER BY MCTPV_CD, LCLGV_CD

SELECT *
FROM LCLGV_AOD_500_STATS
WHERE 1=1

	AND CRTR_YR = (SELECT MAX(CRTR_YR) FROM LCLGV_AOD_500_STATS)


	AND CRTR_YR = #{shYear}


	AND MCTPV_CD = #{shMctpv}

		AND LCLGV_CD = #{shLclgv}

	ORDER BY MCTPV_CD, LCLGV_CD


	ORDER BY MCTPV_CD, LCLGV_CD

SELECT *
FROM LCLGV_AOD_MAX_AMT_STATS
WHERE 1=1

	AND CRTR_YR = (SELECT MAX(CRTR_YR) FROM LCLGV_AOD_MAX_AMT_STATS)


	AND CRTR_YR = #{shYear}


	AND MCTPV_CD = #{shMctpv}

